public class ZooTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("Rabbit dailyCost", 2.5, new Zoo.Rabbit().dailyCost());
        Animal2 viaBase = new Zoo.Rabbit();
        check("Rabbit through an Animal2 reference", 2.5, viaBase.dailyCost());
        check("Lion dailyCost (provided)", 30.0, new Lion().dailyCost());
        check("lion + rabbit", 32.5,
                Zoo.totalDailyCost(new Animal2[] { new Lion(), new Zoo.Rabbit() }));
        check("two lions + rabbit", 62.5,
                Zoo.totalDailyCost(new Animal2[] { new Lion(), new Lion(), new Zoo.Rabbit() }));
        check("two rabbits", 5.0,
                Zoo.totalDailyCost(new Animal2[] { new Zoo.Rabbit(), new Zoo.Rabbit() }));
        check("empty zoo", 0.0, Zoo.totalDailyCost(new Animal2[0]));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

