abstract class Animal2 {
    abstract double dailyCost();
}

class Lion extends Animal2 {
    @Override
    double dailyCost() {
        return 30.0;
    }
}

public class Zoo {

    public static class Rabbit extends Animal2 {
        @Override
        double dailyCost() {
            return 2.5;
        }
    }

    public static double totalDailyCost(Animal2[] animals) {
        double total = 0.0;
        for (Animal2 animal : animals) {
            total += animal.dailyCost();
        }
        return total;
    }
}
